#!/usr/bin/env python3
"""Read-only campaign validation; --write exports reconciled core/H2 observations.

Does not launch servers, compile code, or generate load. Component/allocation
patterns are relative to artifacts/performance-2026-10-20 and accept {variant}
and {trial}. Each must identify exactly baseline/candidate files, never globs.
"""
import argparse,collections,csv,hashlib,json,math,re,statistics
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
ART=ROOT/'artifacts/performance-2026-10-20'; BENCH=ROOT/'artifacts/bench'; OUT=ROOT/'benches/results'
CASES={0:('plain','/plaintext',0,'dynamic'),1:('plain','/users/42',0,'dynamic'),2:('plain','/error',0,'dynamic'),3:('plain','/echo',1024,'dynamic'),4:('h2','/error',0,'maximus'),5:('h2','/echo',131072,'maximus'),6:('plain','/plaintext',0,'maximus')}
METRICS=['rps','cpu_us_per_request','p50_ms','p99_ms','p999_ms','rss_kib','peak_rss_kib','cpu_interval_seconds','server_cpu_percent','client_cpu_percent']
parser=argparse.ArgumentParser(description=__doc__)
parser.add_argument('--component-pattern');parser.add_argument('--allocation-pattern')
parser.add_argument('--baseline-manifest',default='core-h2-baseline-manifest.json')
parser.add_argument('--candidate-manifest',required=True,help='Exact frozen candidate manifest filename, such as core-h2-tuple-manifest.json')
parser.add_argument('--candidate-build-log',required=True)
parser.add_argument('--expected-binary-hash',required=True)
parser.add_argument('--fixture-outcomes',required=True,help='Exact JSON filename listing all 24 fixture process outcomes')
parser.add_argument('--write',action='store_true')
args=parser.parse_args(); observed=set(); rows=[]; envs=[]
def read_json(p):observed.add(p);return json.loads(p.read_text())
def read_csv(p):observed.add(p);return list(csv.DictReader(p.open()))
def hash_file(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def require(test,message):
 if not test:raise ValueError(message)
require(re.fullmatch('[0-9a-f]{64}',args.expected_binary_hash) is not None,'expected binary hash must be SHA-256')
build_path=ART/args.candidate_build_log; observed.add(build_path); build_text=build_path.read_text()
build_hashes=re.findall(r'^([0-9a-f]{64})\s+\S*/maximus-comparison\s*$',build_text,re.MULTILINE)
require(build_hashes==[args.expected_binary_hash],'candidate comparison hash does not match selected build log')
require('Finished `release` profile' in build_text,'candidate build log lacks completed release build')
def metric(d,k,f):return d['metrics'][k]['values'][f]
def validate_summary(p,row,generator):
 d=read_json(p); count=metric(d,'http_reqs','count')
 require(isinstance(count,(int,float)) and math.isfinite(count) and count>0 and count==int(count),f'{p}: invalid count')
 require(metric(d,'checks','passes')==count and metric(d,'checks','fails')==0,f'{p}: response validation mismatch')
 require(metric(d,'http_req_failed','passes')==0,f'{p}: failed responses')
 if generator=='k6':
  require(metric(d,'iteration_starts','count')==count==metric(d,'iterations','count'),f'{p}: incomplete iterations')
  require(d['metrics'].get('dropped_iterations',{}).get('values',{}).get('count',0)==0,f'{p}: drops')
 else:
  require(metric(d,'network_errors','count')==0,f'{p}: network errors')
  require(metric(d,'status_error_responses','count')==(count if row['path']=='/error' else 0),f'{p}: status accounting')
 return d,count
for label,generator,cases in [('core-h2-wrk','wrk',[0,1,2,3,6]),('core-h2-tls','k6',[4,5])]:
 outcomes=read_json(BENCH/f'{label}-outcomes.json'); expected={f'{label}-{r}-{c}-{v}' for r in range(3) for c in cases for v in ['baseline','candidate']}
 require(len(outcomes)==len(expected) and {x['label'] for x in outcomes}==expected,f'{label}: incomplete outcomes')
 require(all(x['passed'] and x['exit']==0 for x in outcomes),f'{label}: failed targets preserved; campaign unqualified')
 for round in range(3):
  for case in cases:
   protocol,path,body,engine=CASES[case]
   for variant in ['baseline','candidate']:
    trial=f'{label}-{round}-{case}-{variant}'; env=read_json(BENCH/f'{trial}-environment.json'); envs.append(dict(trial_label=trial,campaign_case=case,**env))
    require(env['args']['generator']==generator and env['args']['protocol']==protocol,f'{trial}: generator/protocol identity')
    require(env['args']['workers']==1 and env['args']['vus']==64 and env['args']['rates']=='0' and env['args']['client_cpus']=='1,2' and env['args']['sample_seconds']==0,f'{trial}: unexpected placement/load/sampling configuration')
    require(env['args']['body_bytes']==(131072 if case==5 else 1024),f'{trial}: unexpected body-size setting')
    rr=read_csv(BENCH/f'{trial}.csv'); wanted={engine} if variant=='baseline' else {engine,'hyper','axum'}
    require(len(rr)==len(wanted) and {r['engine'] for r in rr}==wanted,f'{trial}: missing/duplicate engine rows')
    for r in rr:
     require((r['protocol'],r['path'],int(r['body_bytes']),r['generator'])==(protocol,path,body,generator),f'{trial}: workload identity')
     require(r['workers']=='1' and r['offered_rps']=='0' and r['repeat']=='0',f'{trial}: CSV workload configuration differs')
     require(all(float(r[k])==0 for k in ['failures','checks_failed','network_errors','dropped','exit']),f'{trial}: invalid row')
     require(all(math.isfinite(float(r[k])) and float(r[k])>=0 for k in METRICS),f'{trial}: invalid numeric observation')
     stem=f"{trial}-{r['engine']}-{path.strip('/').replace('/','-')}-w1-r0-n0"
     validate_summary(BENCH/f'{stem}-warmup.json',r,generator)
     summary,count=validate_summary(BENCH/f'{stem}.json',r,generator)
     require(float(r['requests'])==count,f'{trial}: CSV/JSON response count mismatch')
     for column,key,field in [('rps','http_reqs','rate'),('p50_ms','http_req_duration','med'),('p99_ms','http_req_duration','p(99)'),('p999_ms','http_req_duration','p(99.9)')]:
      require(math.isclose(float(r[column]),metric(summary,key,field),rel_tol=1e-9,abs_tol=1e-8),f'{trial}: {column} CSV/JSON mismatch')
     if generator=='k6':require(float(r['iterations_started'])==count==float(r['iterations_completed']),f'{trial}: CSV iterations')
     else:require(r['iterations_started']==r['iterations_completed']=='',f'{trial}: invented wrk iteration count')
     rows.append(dict(trial_label=trial,variant=variant,campaign_round=round,case=case,**r))
require(len(rows)==84,'expected exactly 60 wrk +24 k6 rows')
for variant in ['baseline','candidate']:
 hashes={e['binary_sha256'].split()[0] for e in envs if e['trial_label'].endswith('-'+variant)}
 require(len(hashes)==1,f'{variant}: mixed binary identities')
 if variant=='baseline':require(hashes=={'be05e0aea314cfdda839441c4c3c923e4cae9c8100f4836f382d7ca1e703e8f2'},'baseline binary does not reproduce reviewed original')
 else:require(hashes=={args.expected_binary_hash},'campaign candidate binary differs from selected build')
for gen in ['wrk','k6']:
 cohort=[e for e in envs if e['args']['generator']==gen]
 require(len({e['workload_sha256'] for e in cohort})==1,f'{gen}: mixed workload hashes')
 images={'rust:1.96-bookworm','maximus-tools:latest' if gen=='wrk' else 'grafana/k6:1.6.0'}
 require(all(set(e['image_ids'])==images for e in cohort),f'{gen}: missing or unexpected image identities')
 for image in images:
  ids={e['image_ids'][image] for e in cohort}
  require(len(ids)==1 and all(isinstance(value,str) and value.startswith('sha256:') for value in ids),f'{gen}: unstable {image} image ID')
 for case in {e['campaign_case'] for e in cohort}:
  settings=['duration','workers','vus','body_bytes','rates','client_cpus','sample_seconds']
  signatures={tuple(e['args'][name] for name in settings) for e in cohort if e['campaign_case']==case}
  require(len(signatures)==1,f'{gen} case {case}: mixed workload settings')
require(len({e['image_ids']['rust:1.96-bookworm'] for e in envs})==1,'Rust image differs between generators')
require(len({e.get('certificate_sha256') for e in envs if e['args']['protocol']=='h2'})==1,'TLS certificate identity differs')
require(all(e.get('certificate_sha256') for e in envs if e['args']['protocol']=='h2'),'missing TLS certificate identity')
def stats(rs,keys):
 return {k:dict(median=statistics.median(v),minimum=min(v),maximum=max(v),samples=v) for k in keys for v in [[float(r[k]) for r in rs]]}
groups=collections.defaultdict(list)
for r in rows:groups[(r['generator'],r['case'],r['engine'],r['variant'])].append(r)
summaries=[dict(generator=k[0],case=k[1],engine=k[2],variant=k[3],statistics=stats(v,METRICS)) for k,v in groups.items()]
pairs=[]
for k,rs in groups.items():
 if k[3]!='baseline':continue
 candidates=groups[(*k[:3],'candidate')]
 for b,c in zip(rs,candidates):
  require(b['campaign_round']==c['campaign_round'],'pair round mismatch')
  pairs.append(dict(generator=k[0],case=k[1],round=b['campaign_round'],baseline=b['trial_label'],candidate=c['trial_label'],percent_changes={m:100*(float(c[m])/float(b[m])-1) for m in METRICS}))
fixture_outcomes=read_json(ART/args.fixture_outcomes)
expected_fixture_keys={(kind,variant,trial) for kind,n in [('components',7),('allocations',5)] for variant in ['baseline','candidate'] for trial in range(n)}
require(len(fixture_outcomes)==24 and {(x['kind'],x['variant'],x['repeat']) for x in fixture_outcomes}==expected_fixture_keys,'fixture outcomes must identify exactly all 24 processes')
require(all(x['exit']==0 for x in fixture_outcomes),'one or more fixture processes exited nonzero')
def fixture_rows(pattern,n,kind,identifier,row_count):
 if not pattern:return None
 require('{variant}' in pattern and '{trial}' in pattern and '*' not in pattern,'use exact fixture pattern')
 result=[]; names=None; counts={}
 for v in ['baseline','candidate']:
  for trial in range(n):
   path=ART/pattern.format(variant=v,trial=trial); records=read_csv(path)
   current={r[identifier] for r in records}
   require(len(records)==row_count and len(current)==row_count,f'{path}: expected {row_count} distinct rows')
   if names is None:names=current
   require(current==names,f'{path}: fixture rows changed')
   for row in records:
    count_key='operations' if kind=='components' else 'requests'; count=float(row[count_key])
    require(math.isfinite(count) and count>0 and count==int(count),f'{path}: invalid operation count')
    previous=counts.setdefault(row[identifier],count); require(previous==count,f'{path}: fixture operation count changed')
    for key,value in row.items():
     if key!=identifier:require(math.isfinite(float(value)) and float(value)>=0,f'{path}: invalid numeric field {key}')
   result.extend(dict(variant=v,trial=trial,**r) for r in records)
 return result
components=fixture_rows(args.component_pattern,7,'components','component',8)
allocations=fixture_rows(args.allocation_pattern,5,'allocations','path',18)
manifest={v:read_json(ART/name) for v,name in [('baseline',args.baseline_manifest),('candidate',args.candidate_manifest)]}
for fixture in ['benches/baselines/src/main.rs','benches/baselines/src/bin/allocations.rs','benches/baselines/src/bin/components.rs']:
 require(fixture in manifest['baseline'] and manifest['baseline'][fixture]==manifest['candidate'].get(fixture),f'fixture source mismatch: {fixture}')
result=dict(scope='Error borrowed bodies, H2-only persistent shutdown, rejected CONNECT. Router original. Exact candidate is identified by the explicitly selected manifest.',baseline_manifest=args.baseline_manifest,candidate_manifest=args.candidate_manifest,candidate_build_log=args.candidate_build_log,expected_candidate_binary_sha256=args.expected_binary_hash,fixture_outcomes=fixture_outcomes,status='observations reconciled; finite measurements do not establish universal non-regression',rows=len(rows),checked_responses=sum(int(r['requests']) for r in rows),summaries=summaries,pairs=pairs,environments=envs,source_manifests=manifest,components=components,allocations=allocations,artifact_sha256={str(p.relative_to(ROOT)):hash_file(p) for p in sorted(observed)},analysis_script=Path(__file__).read_text())
print(json.dumps({k:result[k] for k in ['status','rows','checked_responses']},indent=2))
if args.write:
 require(components is not None and allocations is not None,'--write requires component/allocation patterns')
 for dest,data in [('core-h2-trials.csv',rows),('core-h2-components.csv',components),('core-h2-allocations.csv',allocations)]:
  with (OUT/dest).open('w') as f:w=csv.DictWriter(f,fieldnames=list(data[0]));w.writeheader();w.writerows(data)
 (OUT/'core-h2-evidence.json').write_text(json.dumps(result,indent=2)+'\n')
